#include <stdio.h>
#include <sys/wait.h>
#include <unistd.h>

int main(void) {
    printf("parent: pid=%d\n", getpid());
    fflush(stdout);
    pid_t pid = fork();
    if (pid == 0) {
        printf("child:  pid=%d parent=%d\n", getpid(), getppid());
        return 7;
    }
    int status;
    waitpid(pid, &status, 0);
    printf("parent: child %d exited with code %d\n", pid, WEXITSTATUS(status));
    return 0;
}

