#include <stdio.h>
#include <sys/wait.h>
#include <unistd.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "usage: %s command [args]\n", argv[0]);
        return 2;
    }
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return 1;
    }
    if (pid == 0) {
        execvp(argv[1], &argv[1]);
        perror(argv[1]);
        _exit(127);
    }
    int status;
    waitpid(pid, &status, 0);
    if (WIFEXITED(status))
        printf("[exit %d]\n", WEXITSTATUS(status));
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/resource.h>
#include <sys/wait.h>
#include <unistd.h>

#define SIZE (64UL * 1024 * 1024)

static long minor_faults(void) {
    struct rusage r;
    getrusage(RUSAGE_SELF, &r);
    return r.ru_minflt;
}

int main(int argc, char **argv) {
    int write_mode = argc > 1 && strcmp(argv[1], "write") == 0;
    int hold = argc > 1 && strcmp(argv[1], "hold") == 0;
    long page = sysconf(_SC_PAGESIZE);
    char *buf = mmap(NULL, SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    madvise(buf, SIZE, MADV_NOHUGEPAGE);   /* keep the numbers easy to read */
    memset(buf, 1, SIZE);                  /* the parent touches every page */

    pid_t pid = fork();
    if (pid == 0) {
        if (hold) {                        /* touch nothing, just wait so we can inspect */
            sleep(3);
            return 0;
        }
        long before = minor_faults();
        volatile char sum = 0;
        for (size_t i = 0; i < SIZE; i += page) {
            if (write_mode) buf[i] = 2;
            else sum += buf[i];
        }
        printf("child %s %lu pages: %ld page faults\n",
               write_mode ? "wrote" : "read", SIZE / page, minor_faults() - before);
        return 0;
    }
    waitpid(pid, NULL, 0);
    return 0;
}
